.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ─── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 0;
  z-index: 9999;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  border-radius: 0 0 0.5rem 0;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
}

/* ─── Page ─────────────────────────────────────────────────────── */
body {
  min-height: 100dvh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 2rem 1rem;
  background-color: var(--bg-page);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
}

main {
  width: 100%;
  max-width: 36rem;
}

/* ─── Card ─────────────────────────────────────────────────────── */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 1rem;
  padding: 2.5rem 2rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
}

.form-intro {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

/* ─── Live-region messages ─────────────────────────────────────── */
#form-error-summary,
#form-success {
  /* visually hidden when empty; visible when content is injected */
  display: block;
}

#form-error-summary:not(:empty) {
  margin-bottom: 1.25rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--error-border);
  border-radius: 0.5rem;
  background: var(--error-bg);
  color: var(--error);
  font-size: 0.9rem;
}

#form-success:not(:empty) {
  margin-bottom: 1.25rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--success);
  border-radius: 0.5rem;
  background: var(--success-bg);
  color: var(--success);
  font-size: 0.9rem;
}

/* ─── Form layout ──────────────────────────────────────────────── */
form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ─── Form field ───────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-label);
  letter-spacing: 0.01em;
}

.required-marker {
  color: var(--required-star);
  font-weight: 700;
  margin-left: 0.125rem;
}

.optional-marker {
  color: var(--optional-text);
  font-weight: 400;
  font-size: 0.825rem;
}

/* ─── Inputs ───────────────────────────────────────────────────── */
input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  background: var(--bg-input);
  border: 1.5px solid var(--border-subtle);
  border-radius: 0.5rem;
  color: var(--text-primary);
  font-family: inherit;
  font-size: 1rem;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  -webkit-appearance: none;
  appearance: none;
}

input::placeholder {
  color: var(--text-secondary);
  opacity: 0.6;
}

input:hover {
  border-color: #4a5070;
}

input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 142, 245, 0.25);
}

/* Invalid state — only applied via JS after first validation attempt */
input[aria-invalid="true"] {
  border-color: var(--error-border);
}

input[aria-invalid="true"]:focus {
  border-color: var(--error-border);
  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.25);
}

/* ─── Help & error text ────────────────────────────────────────── */
.field-help {
  font-size: 0.8125rem;
  color: var(--text-secondary);
}

.field-error {
  font-size: 0.8125rem;
  color: var(--error);
  min-height: 0;           /* collapses when empty */
  font-weight: 500;
}

.field-error:empty {
  display: none;           /* fully removes gap when no error */
}

/* ─── Submit button ────────────────────────────────────────────── */
button[type="submit"] {
  margin-top: 0.5rem;
  padding: 0.75rem 1.5rem;
  background: var(--accent);
  border: 2px solid transparent;
  border-radius: 0.5rem;
  color: #fff;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s ease, box-shadow 0.15s ease;
  align-self: flex-start;
}

button[type="submit"]:hover {
  background: var(--accent-hover);
}

button[type="submit"]:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

button[type="submit"]:active {
  transform: translateY(1px);
}

/* ─── Reflow: narrow viewports ─────────────────────────────────── */
@media (max-width: 400px) {
  .form-card {
    padding: 1.5rem 1rem;
  }

  h1 {
    font-size: 1.375rem;
  }

  button[type="submit"] {
    width: 100%;
  }
}
