}

/* ─── Forced-colors / high-contrast support ────────────────────── */
@media (forced-colors: active) {
  :root {
    --border-focus: Highlight;
    --error:        Mark;
  }
}

/* ─── Reduced-motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition: none !important;
  }
}

/* ─── Screen-reader only utility ───────────────────────────────── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ─── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -9999px;
  left: 0;
  z-index: 9999;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  text-decoration: none;
  border-radius: 0 0 0.5rem 0;
}

.skip-link:focus {
  top: 0;
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
}

/* ─── Page ─────────────────────────────────────────────────────── */
body {
  min-height: 100dvh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 2rem 1rem;
  background-color: var(--bg-page);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
}

main {
  width: 100%;
  max-width: 36rem;
}

/* ─── Card ─────────────────────────────────────────────────────── */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 1rem;
  padding: 2.5rem 2rem;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.375rem;
}

.form-intro {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

/* ─── Live-region messages ─────────────────────────────────────── */
#form-error-summary,
#form-success {
  /* visually hidden when empty; visible when content is injected */
  display: block;
}

#form-error-summary:not(:empty) {
  margin-bottom: 1.25rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--error-border);
  border-radius: 0.5rem;
  background: var(--error-bg);
  color: var(--error);
  font-size: 0.9rem;
}

#form-success:not(:empty) {
  margin-bottom: 1.25rem;
  padding: 0.875rem 1rem;
