  border-radius: 0.5rem;
  background: var(--success-bg);
  color: var(--success);
  font-size: 0.9rem;
}

/* ─── Form layout ──────────────────────────────────────────────── */
form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ─── Form field ───────────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-label);
  letter-spacing: 0.01em;
}

.required-marker {
