  font-size: 0.825rem;
}

/* ─── Inputs ───────────────────────────────────────────────────── */
input {
  width: 100%;
  padding: 0.625rem 0.875rem;
  background: var(--bg-input);
  border: 1.5px solid var(--border-subtle);
  border-radius: 0.5rem;
