}

input::placeholder {
  color: var(--text-secondary);
  opacity: 0.6;
}

input:hover {
  border-color: #4a5070;
}

input:focus {
  outline: none;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 142, 245, 0.25);
}

/* Invalid state — only applied via JS after first validation attempt */
input[aria-invalid="true"] {
  border-color: var(--error-border);
}

input[aria-invalid="true"]:focus {
  border-color: var(--error-border);
