    <script>
(() => {
  const form = document.getElementById('contact-form');
  const errorSummary = document.getElementById('form-error-summary');
  const successMsg = document.getElementById('form-success');

  const fields = {
    'full-name': {
      el: document.getElementById('full-name'),
      errorEl: document.getElementById('full-name-error'),
      validate(val) {
        if (!val.trim()) return 'Error: Full name is required.';
        return null;
      },
    },
    email: {
      el: document.getElementById('email'),
      errorEl: document.getElementById('email-error'),
      validate(val) {
        if (!val.trim()) return 'Error: Email address is required.';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim()))
          return 'Error: Enter a valid email address, like name@example.com.';
        return null;
      },
    },
  };

  function setFieldError(field, message) {
    const { el, errorEl } = field;
    if (message) {
      el.setAttribute('aria-invalid', 'true');
      errorEl.textContent = message;
    } else {
      el.removeAttribute('aria-invalid');
      errorEl.textContent = '';
    }
  }

  function validateAll() {
    const errors = [];
    for (const key of Object.keys(fields)) {
      const field = fields[key];
      const msg = field.validate(field.el.value);
      setFieldError(field, msg);
      if (msg) errors.push({ field, msg });
    }
    return errors;
  }

  let hasAttempted = false;

  Object.values(fields).forEach(({ el, validate, errorEl }) => {
    el.addEventListener('input', () => {
      if (!hasAttempted) return;
      const msg = validate(el.value);
      if (msg) {
        el.setAttribute('aria-invalid', 'true');
        errorEl.textContent = msg;
      } else {
        el.removeAttribute('aria-invalid');
        errorEl.textContent = '';
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    hasAttempted = true;

    errorSummary.textContent = '';
    successMsg.textContent = '';

    const errors = validateAll();

    if (errors.length > 0) {
      errors[0].field.el.focus();
      const count = errors.length;
      errorSummary.textContent =
        `${count} error${count > 1 ? 's' : ''} found. Please correct the highlighted field${count > 1 ? 's' : ''} and try again.`;
      return;
    }

    successMsg.textContent = 'Your message has been sent. We\u2019ll be in touch soon.';
    form.reset();
    hasAttempted = false;
    Object.values(fields).forEach((field) => setFieldError(field, null));
  });
})();
